(7698581, 1263287, 273075, '<td valign="top">I like how the colors show it is night even though it is well exposed</td>', 'I like how the colors show it is night even though it is well exposed', '2021-08-06 01:45:51.000000', NULL, 1),
(7698582, 1263295, 273075, '<td valign="top">Well composed.  Nice point of interest in the subject on the right.</td>', 'Well composed.  Nice point of interest in the subject on the right.', '2021-08-06 01:48:52.000000', NULL, 1),
