(7698595, 1263302, 101668, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2021-08-06 13:24:59.000000', NULL, 1),
(7698779, 1263231, 30049, '<td valign="top">I like this the best because it actually looks like a place you''d go to in the evening for a "Night on the Town".  :-)  An actual PERSON in the photo.  &lt;thumbs up&gt;  Hope you gave her a good tip!</td>', 'I like this the best because it actually looks like a place you''d go to in the evening for a "Night on the Town".  :-)  An actual PERSON in the photo.  <thumbs up>  Hope you gave her a good tip!', '2021-08-09 19:34:17.000000', NULL, 1),
(7698781, 1263295, 30049, '<td valign="top">Nice clear photo, but is this what a "Night on the Town" looks like?  :-}  Well, maybe during a pandemic I guess.</td>', 'Nice clear photo, but is this what a "Night on the Town" looks like?  :-}  Well, maybe during a pandemic I guess.', '2021-08-09 19:35:59.000000', NULL, 1),
(7698782, 1263287, 30049, '<td valign="top">Where''s the festive, fun part?  Some people or action?</td>', 'Where''s the festive, fun part?  Some people or action?', '2021-08-09 19:36:54.000000', NULL, 1),
(7698783, 1263283, 30049, '<td valign="top">Cute, easy way out of actually getting a photo with some nightlife in it.</td>', 'Cute, easy way out of actually getting a photo with some nightlife in it.', '2021-08-09 19:37:33.000000', NULL, 1),
(7698784, 1263299, 30049, '<td valign="top">Ok, this image is getting closer to a "Night on the Town", if only there were some people maybe hanging out at the door, or even better, getting a photo of people (or singular person) at the bar, or on the dance floor, or at a dining table)?</td>', 'Ok, this image is getting closer to a "Night on the Town", if only there were some people maybe hanging out at the door, or even better, getting a photo of people (or singular person) at the bar, or on the dance floor, or at a dining table)?', '2021-08-09 19:38:49.000000', NULL, 1),
(7698785, 1263302, 30049, '<td valign="top">Nice nightscape, but it''s not really much in the way of a "Night on the Town".  Where''s the action, the people, the FUN?</td>', 'Nice nightscape, but it''s not really much in the way of a "Night on the Town".  Where''s the action, the people, the FUN?', '2021-08-09 19:40:09.000000', NULL, 1),
(7698786, 1263298, 30049, '<td valign="top">Nice building, and I imagine it''s a local, well known establishment?  Would be more interesting / fun to see the inside with some people interacting or a smeared ice cream cone on somebody''s face (that''s the general idea / concept).</td>', 'Nice building, and I imagine it''s a local, well known establishment?  Would be more interesting / fun to see the inside with some people interacting or a smeared ice cream cone on somebody''s face (that''s the general idea / concept).', '2021-08-09 19:41:58.000000', NULL, 1),
(7698787, 1263296, 30049, '<td valign="top">How in the world is this a "Night on the Town"?  Take away the title and sorry, IMO, it''s an aerial view of an empty parking lot.  Where''s the people, the fun, the Nightlife?  After viewing the images in this challenge I get the impression it''s a bit like asking our DPC community to take a street portrait (many are nervous to go out and take one or to interact with people, even if from a distance).</td>', 'How in the world is this a "Night on the Town"?  Take away the title and sorry, IMO, it''s an aerial view of an empty parking lot.  Where''s the people, the fun, the Nightlife?  After viewing the images in this challenge I get the impression it''s a bit like asking our DPC community to take a street portrait (many are nervous to go out and take one or to interact with people, even if from a distance).', '2021-08-09 19:44:34.000000', NULL, 1),
(7698788, 1263301, 30049, '<td valign="top">Ghost Town outtake?!  I don''t get the feeling of a "Night on the Town" here whatsoever.  Sorry.</td>', 'Ghost Town outtake?!  I don''t get the feeling of a "Night on the Town" here whatsoever.  Sorry.', '2021-08-09 19:45:25.000000', NULL, 1),
(7698789, 1263290, 30049, '<td valign="top">Oh my goodness.  Really?  Where''s the "Town", where''s the fun, where''s the people?  Sorry, not getting this take on the challenge theme whatsoever.</td>', 'Oh my goodness.  Really?  Where''s the "Town", where''s the fun, where''s the people?  Sorry, not getting this take on the challenge theme whatsoever.', '2021-08-09 19:46:24.000000', NULL, 1),
(7698790, 1263289, 30049, '<td valign="top">Wow.  Ok.  Abstract take it is.  :-}  So ... where''s the action, the fun, the people, you know, a "Night on the Town"?</td>', 'Wow.  Ok.  Abstract take it is.  :-}  So ... where''s the action, the fun, the people, you know, a "Night on the Town"?', '2021-08-09 19:47:18.000000', NULL, 1),
(7698793, 1263270, 30049, '<td valign="top">Take away the title of this entry and what do you have; a billboard photo?  Sorry, not feeling this for the challenge theme.  Was expecting more fun, maybe some people, a glitzy (or even moderately lit) bar, restaurant, amusement park ... ?</td>', 'Take away the title of this entry and what do you have; a billboard photo?  Sorry, not feeling this for the challenge theme.  Was expecting more fun, maybe some people, a glitzy (or even moderately lit) bar, restaurant, amusement park ... ?', '2021-08-09 19:50:42.000000', NULL, 1),
(7698794, 1263278, 30049, '<td valign="top">Oh gosh.</td>', 'Oh gosh.', '2021-08-09 20:03:52.000000', NULL, 1),
(7698795, 1263282, 30049, '<td valign="top">Wish you''d gotten a little closer, but it does appear to actually be a lively spot where something is happening.  Thanks for that.  Rare in this challenge.</td>', 'Wish you''d gotten a little closer, but it does appear to actually be a lively spot where something is happening.  Thanks for that.  Rare in this challenge.', '2021-08-09 20:05:25.000000', NULL, 1),
